/bin/bash -lc "cat <<'EOF' > lib/analytics.ts
export type PageViewEvent = {
  path: string;
  timestamp: string;
  userAgent?: string;
};

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT;

export async function logPageView(event: PageViewEvent) {
  if ("'!ANALYTICS_ENDPOINT) {
    console.info('"'[analytics] Page view', event);
    return;
  }

  const response = await fetch(ANALYTICS_ENDPOINT, {
    method: 'POST',
    headers: {
      'content-type': 'application/json'
    },
    body: JSON.stringify(event),
    keepalive: true
  });

  if ("'!response.ok) {
    console.warn('"'[analytics] Failed to log page view', {
      status: response.status,
      statusText: response.statusText
    });
  }
}
EOF"

/bin/bash -lc "cat <<'EOF' > app/page.tsx
import { after } from 'next/server';
import { headers } from 'next/headers';

import { logPageView } from '../lib/analytics';

export default function Home() {
  const requestHeaders = headers();
  const userAgent = requestHeaders.get('user-agent') ?? undefined;

  after(async () => {
    await logPageView({
      path: '/',
      timestamp: new Date().toISOString(),
      userAgent
    });
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by.</p>
    </main>
  );
}
EOF"
